INSERT INTO "pitaya"."articles" ("slug", "title", "content", "is_draft", "published_at") VALUES ('pitabooth-pourquoi-je-construis-mon-propre-photobooth', 'PitaBooth : pourquoi je construis mon propre photobooth', '{"category":"Coulisses","excerpt":"Un appareil photo, une interface tactile et une idée simple : laisser à chacun le temps de créer un souvenir qui lui ressemble. Voici les coulisses de PitaBooth, mon photobooth en développement.","interest":4,"readingTime":4,"visual":{"eyebrow":"Projet en cours","headline":"Un souvenir à créer, pas seulement une photo à prendre","text":"PitaBooth est encore en développement. Je construis une expérience simple à utiliser pendant un événement, de la prise de vue au souvenir final."},"pullQuote":"Le meilleur photobooth est celui qu''on oublie pendant la fête, mais dont on garde les images longtemps après.","introduction":[{"text":"Un photobooth, c''est souvent le moment où les invités se détendent enfin devant l''objectif. On se rapproche, on tente une pose improbable, on recommence, et l''on repart avec un souvenir que personne n''avait prévu. C''est cette spontanéité que j''ai envie de préserver avec PitaBooth, un projet que je développe pour les événements photographiés par Pitaya Photo."},{"text":"Je ne voulais pas simplement poser un appareil photo dans un coin. Je voulais imaginer tout le parcours : une interface tactile facile à comprendre, une vraie prise de vue, la liberté de choisir son image et un rendu final qui mérite d''être gardé. Le projet n''est pas encore une prestation disponible ; voici ce que je cherche à construire."}],"sections":[{"title":"Une expérience pensée pour les invités","paragraphs":[{"text":"À une fête, personne ne devrait avoir besoin d''un mode d''emploi. Mon objectif est un parcours court : se placer devant l''appareil, voir son cadrage, lancer la prise de vue, puis découvrir le résultat. Si la photo ne plaît pas, on doit pouvoir recommencer simplement."},{"text":"Je travaille sur une interface tactile qui laisse toute sa place à l''image et à l''ambiance de l''événement. Le compte à rebours, les indications et les boutons doivent rester évidents, y compris pour quelqu''un qui découvre la borne pour la première fois."}]},{"title":"Garder la main sur son souvenir","paragraphs":[{"text":"Le prototype permet de travailler le rendu après la prise de vue : luminosité, contraste, saturation et styles prédéfinis font partie des pistes déjà présentes dans l''interface. Je tiens surtout à une chose : l''aperçu affiché doit correspondre à l''image finale. Une retouche séduisante à l''écran n''a aucun intérêt si le tirage raconte autre chose."},{"text":"Le souvenir imprimé reste au cœur de l''idée. C''est un objet que l''on emporte, que l''on colle sur un frigo ou que l''on retrouve des années plus tard. J''étudie aussi une récupération numérique simple, par exemple depuis la galerie de l''événement ou un QR code, mais cette partie est encore à construire."}]},{"title":"Pourquoi le développer moi-même ?","paragraphs":[{"text":"En développant PitaBooth, je peux ajuster l''expérience au rythme d''un mariage, d''un anniversaire ou d''un événement d''entreprise, plutôt que d''imposer le même parcours partout. Je veux pouvoir soigner la prise de vue, le rendu, puis la façon dont les invités récupèrent leurs images."},{"text":"Il reste des essais à mener sur la fiabilité de l''appareil connecté, l''impression et la continuité du parcours pendant une soirée entière. Je préfère montrer le projet tel qu''il est : une borne en construction, avec une direction claire, plutôt que d''annoncer trop tôt des fonctions qui ne sont pas prêtes. Je partagerai la suite au fur et à mesure de son avancée."}]}],"sources":[]}'::jsonb, false, '2026-10-09T20:00:00.000Z'::timestamptz) ON CONFLICT ("slug") DO NOTHING;
